-- ===========================================================================
-- 0008 — Permission catalog, role grants, and operational thresholds
--
-- GENERATED FILE. Do not edit by hand.
--
-- Produced by buildPermissionSeedSql() in src/domain/permissions/seed.ts from
-- the catalog in actions.ts, the grants in roles.ts, and the threshold keys in
-- settings/thresholds.ts. Those files are the single definition (ADR-022,
-- ADR-025); this migration is their projection into the database, which is
-- where RLS can read them.
--
-- To change a grant: edit roles.ts, run `npm run seed:permissions`, commit both.
-- seed.test.ts fails if this file and the catalog disagree.
-- ===========================================================================

-- Idempotent: re-running reconciles the database with the catalog rather than
-- appending to it. A grant removed from roles.ts must disappear here too, or
-- revoking a permission would require a hand-written migration — which is the
-- drift ADR-022 exists to prevent.

-- ---------------------------------------------------------------------------
-- permission — the catalog
-- ---------------------------------------------------------------------------

insert into permission (key, permission_group, level, description) values
  ('case.read', 'cases', 'row', 'See a case and everything that hangs off it.'),
  ('case.create', 'cases', 'row', 'Open a new case. A lead is a case (ADR-008), so this is the telecaller''s primary action. No row exists yet to scope against.'),
  ('case.update', 'cases', 'row', 'Change a case''s own fields and its party, property and requirement rows. Stage movement is not covered here — stages move through transitions.'),
  ('case.assign', 'cases', 'row', 'Change a case''s accountable owner (BR-011). Always an event.'),
  ('case.hold', 'cases', 'row', 'Place or lift a hold, with reason and follow-up date (ADR-021).'),
  ('case.mark_lost', 'cases', 'row', 'End a case as lost, with a reason from the controlled list (BR-013).'),
  ('case.reopen', 'cases', 'row', 'Return a lost case to the stage it was lost from.'),
  ('case.close', 'cases', 'row', 'Close a disbursed case. Closing asserts the invoice is raised, which is why it is Finance''s and not the owner''s.'),
  ('person.read', 'people-and-organisations', 'row', 'See a person and their identifiers, aliases and employment. Deliberately not narrowable: a telecaller must be able to discover that the caller is an existing customer, which is the product''s central promise (Principle #4).'),
  ('person.create', 'people-and-organisations', 'row', 'Record a new person. No row exists yet to scope against.'),
  ('person.update', 'people-and-organisations', 'row', 'Amend a person, their identifiers, aliases, employment, referrer profile and bank-contact relationships.'),
  ('person.merge', 'people-and-organisations', 'row', 'Merge two people into one, leaving the loser as a redirecting tombstone (BR-004). Reversible (BR-005), which is what makes restricting it tolerable.'),
  ('person.override_duplicate', 'people-and-organisations', 'row', 'Create a person the system believes is a duplicate. Requires a reason and writes an event (BR-053).'),
  ('organisation.read', 'people-and-organisations', 'row', 'See an organisation, its aliases, its lender profile and its bank contacts. Covers employers, borrowing firms, builders, banks and branches (ADR-014).'),
  ('organisation.create', 'people-and-organisations', 'row', 'Record a new organisation. Users never do this explicitly — typing a name resolves or creates one in the background (ADR-009).'),
  ('organisation.update', 'people-and-organisations', 'row', 'Amend an organisation, its aliases and its bank contacts. Found missing by the consistency audit — the catalog had create and merge but no update.'),
  ('organisation.merge', 'people-and-organisations', 'row', 'Merge two organisations, following the same tombstone-and-alias rules as people (BR-006). Near-matches are suggested, never auto-merged.'),
  ('property.read', 'people-and-organisations', 'row', 'See a property. Not narrowable for the same reason as person: one property appears across a purchase, a later top-up and a balance transfer, and recognising that is the point.'),
  ('property.create', 'people-and-organisations', 'row', 'Record a property. Duplicates are tolerated here — properties are found through their case and their people, which are well identified.'),
  ('property.update', 'people-and-organisations', 'row', 'Amend a property''s address, valuation and document numbers.'),
  ('property.merge', 'people-and-organisations', 'row', 'Merge two property records. Expected to be rare and requires an extra confirmation — wrongly linking two properties has a financial consequence far worse than a duplicate row (Identity Resolution Part 5).'),
  ('employment.read', 'people-and-organisations', 'row', 'See a person''s employment history. Employment type drives requirement generation, so the login desk needs it on every file.'),
  ('employment.record', 'people-and-organisations', 'row', 'Add or amend an employment relationship, including declared income. One permission rather than create plus update: an employment row is corrected far more often than a new one is genuinely added, and splitting them would mean every role that holds one holds the other.'),
  ('document.read', 'documents', 'row', 'See and download a document. Narrowable, unlike person: a document is the sensitive artefact, and `own` reaches it through the cases that reference it.'),
  ('document.upload', 'documents', 'row', 'Add a document, or a new version of one. Versions accumulate; nothing is overwritten in place (BR-031).'),
  ('document.verify', 'documents', 'row', 'Mark a document checked. Always attributed to a named human — the system never verifies (BR-032).'),
  ('document.delete_version', 'documents', 'row', 'Remove a document version. **Granted to nobody, deliberately.** Documents are versioned and never overwritten (BR-031), and a replaced document may be the one a bank already saw. Listed so the decision is explicit rather than accidental.'),
  ('requirement.waive', 'documents', 'row', 'Excuse a requirement, recording who, when and why (BR-035). A waiver sends an incomplete file to a bank; safety comes from attribution, not rarity.'),
  ('submission.read', 'banking', 'row', 'See a case''s submissions and their statuses — the grid that sits beneath the case stage and makes the two axes obvious (ADR-004).'),
  ('submission.create', 'banking', 'row', 'Send a file to a bank branch. A corrected file returning to the same branch is a new submission, never a reset of the old one (Workflow.md).'),
  ('submission.update_status', 'banking', 'row', 'Move a submission''s status, including recording a rejection with its standardised reason and the bank''s own wording (ADR-028).'),
  ('offer.read', 'banking', 'row', 'See what a bank came back with — amount, rate, tenure, conditions.'),
  ('offer.record', 'banking', 'row', 'Enter or revise an offer against a submission. A revision is a new offer row: comparing it against the original is the conversation with the customer.'),
  ('offer.accept', 'banking', 'row', 'Record that the customer accepted an offer. At most one per submission (BR-025); the unaccepted submissions then go to Withdrawn, not Rejected.'),
  ('task.read', 'work-and-communication', 'row', 'See tasks. At `own` this is the calling screen''s work list; at `all` it is how a manager sees what the team is carrying.'),
  ('task.create', 'work-and-communication', 'row', 'Raise a task for oneself. Assigning it to somebody else is `task.assign`, deliberately separate.'),
  ('task.update', 'work-and-communication', 'row', 'Amend or complete a task. Tasks are never deleted — a deleted task hides the fact that work was dropped (BR-041).'),
  ('task.assign', 'work-and-communication', 'row', 'Give a task to somebody else. Every task has exactly one assignee (BR-040).'),
  ('communication.read', 'work-and-communication', 'row', 'See logged calls, WhatsApp, email and meetings. Found missing by the audit — roles could log a communication but nothing said who could read one.'),
  ('communication.log', 'work-and-communication', 'row', 'Record an exchange with a person. Logged against both the person and the case, so a person''s full history is visible from their profile.'),
  ('note.read', 'work-and-communication', 'row', 'Read internal commentary on a case. Found missing by the audit.'),
  ('note.create', 'work-and-communication', 'row', 'Write internal commentary, immutable after a short edit window. Notes are not a place for structured facts — if something is written repeatedly, it wants a field (Principle #11).'),
  ('identifier.view_full', 'sensitive', 'column', 'See an unmasked identifier value — full PAN rather than `ABCxxxxx1F`. Column-level: the person row is visible either way (ADR-026). The only permission whose denial is itself an event, because revealing one value is a per-record disclosure decision rather than a whole-surface one.'),
  ('commercial.view', 'sensitive', 'column', 'See money the customer never sees: commission terms, referrer payouts, login fees, invoice figures. Column-level (ADR-026) — the case, submission and referrer rows are visible without it.'),
  ('event.view', 'sensitive', 'row', 'Read the audit log. Row-level rather than column-level: an event is either yours to see or it is not.'),
  ('user.read', 'administration', 'row', 'See who holds an account and which roles they hold. Held at `all` by every role: colleagues'' names appear on every case, and `own` alone would make a case owner unrenderable.'),
  ('user.manage', 'administration', 'row', 'Create and deactivate accounts. Never delete — a departed employee''s name must survive on every case they touched (BR-062).'),
  ('role.assign', 'administration', 'row', 'Grant and revoke roles. Assignment is runtime data, never a migration (ADR-022).'),
  ('master_data.read', 'administration', 'row', 'Read reference tables — loan products, bank products, document types, rejection reasons, operational thresholds, the permission catalog itself. Held by every role. It exists so that no table is bound to a null permission: ''everyone may read this'' is a decision and should be written down as one (ADR-027).'),
  ('master_data.manage', 'administration', 'row', 'Maintain reference tables — add a bank, a branch, a bank product, a document type, a rejection reason. Not a licence to alter operational records.'),
  ('report.view', 'administration', 'row', 'Read aggregate reporting. Aggregates are computed over rows the user may see.')
on conflict (key) do update set
  permission_group = excluded.permission_group,
  level            = excluded.level,
  description      = excluded.description;

