-- ---------------------------------------------------------------------------
-- operational_threshold — keys are code, values are data (ADR-025)
--
-- The insert is deliberately NOT an upsert of the value: a threshold someone
-- tuned in production must survive a redeploy. Only the key set is reconciled.
-- ---------------------------------------------------------------------------

insert into operational_threshold (key, value_days, description) values
  ('idle_days.new', 1, 'Days a case may sit in "new" before its health degrades.'),
  ('idle_days.contacted', 3, 'Days a case may sit in "contacted" before its health degrades.'),
  ('idle_days.appointment_fixed', 2, 'Days a case may sit in "appointment fixed" before its health degrades.'),
  ('idle_days.documents_pending', 5, 'Days a case may sit in "documents pending" before its health degrades.'),
  ('idle_days.ready_for_submission', 2, 'Days a case may sit in "ready for submission" before its health degrades.'),
  ('idle_days.submitted', 10, 'Days a case may sit in "submitted" before its health degrades.'),
  ('idle_days.sanctioned', 7, 'Days a case may sit in "sanctioned" before its health degrades.'),
  ('idle_days.disbursed', 14, 'Days a case may sit in "disbursed" before its health degrades.'),
  ('offer_expiry_warning_days', 7, 'Days before an offer expires at which a task is raised to the case owner.'),
  ('unverified_document_age_days', 3, 'Days a document may sit received-but-unverified before case health degrades.'),
  ('default_hold_follow_up_days', 14, 'Default follow-up date offered when a case is put on hold.')
on conflict (key) do nothing;

delete from operational_threshold
 where key not in (
       'idle_days.new',
       'idle_days.contacted',
       'idle_days.appointment_fixed',
       'idle_days.documents_pending',
       'idle_days.ready_for_submission',
       'idle_days.submitted',
       'idle_days.sanctioned',
       'idle_days.disbursed',
       'offer_expiry_warning_days',
       'unverified_document_age_days',
       'default_hold_follow_up_days'
     );
